export const getEbayCallbackUrl = (params?: EbayCallbackParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/ebay/callback?${stringifiedParams}` : `/api/ebay/callback`
}

/**
 * @summary eBay OAuth callback
 */
export const ebayCallback = async (params?: EbayCallbackParams, options?: Parameters<typeof customFetch>[1]): Promise<unknown> => {

  return customFetch<unknown>(getEbayCallbackUrl(params),
  {
    ...options,
    method: 'GET'


  }
);}





export const getEbayCallbackQueryKey = (params?: EbayCallbackParams,) => {
    return [
    `/api/ebay/callback`, ...(params ? [params] : [])
    ] as const;
    }


export const getEbayCallbackQueryOptions = <TData = Awaited<ReturnType<typeof ebayCallback>>, TError = ErrorType<void>>(params?: EbayCallbackParams, options?: { query?:UseQueryOptions<Awaited<ReturnType<typeof ebayCallback>>, TError, TData>, request?: SecondParameter<typeof customFetch>}
) => {

const {query: queryOptions, request: requestOptions} = options ?? {};

  const queryKey =  queryOptions?.queryKey ?? getEbayCallbackQueryKey(params);



    const queryFn: QueryFunction<Awaited<ReturnType<typeof ebayCallback>>> = ({ signal }) => ebayCallback(params, { signal, ...requestOptions });





   return  { queryKey, queryFn, ...queryOptions} as UseQueryOptions<Awaited<ReturnType<typeof ebayCallback>>, TError, TData> & { queryKey: QueryKey }
}

export type EbayCallbackQueryResult = NonNullable<Awaited<ReturnType<typeof ebayCallback>>>
export type EbayCallbackQueryError = ErrorType<void>


/**
 * @summary eBay OAuth callback
 */

export function useEbayCallback<TData = Awaited<ReturnType<typeof ebayCallback>>, TError = ErrorType<void>>(
 params?: EbayCallbackParams, options?: { query?:UseQueryOptions<Awaited<ReturnType<typeof ebayCallback>>, TError, TData>, request?: SecondParameter<typeof customFetch>}

 ):  UseQueryResult<TData, TError> & { queryKey: QueryKey } {

  const queryOptions = getEbayCallbackQueryOptions(params,options)

  const query = useQuery(queryOptions) as  UseQueryResult<TData, TError> & { queryKey: QueryKey };

  return withQueryKey(query, queryOptions.queryKey);
}







